   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>

     <script>
       const FormField = () => `
         <div class="form-field">
           <input
             class="checkbox-input"
             type="checkbox"
             id="terms-consent"
             name="termsConsent"
             required
             aria-describedby="terms-helper terms-error"
           >
           <div class="field-copy">
             <label class="checkbox-label" for="terms-consent">
               I agree to the <a href="#terms-summary">Terms of Use</a>
               <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <p class="helper-text" id="terms-helper">
               Required to create your account and continue.
             </p>
             <p class="error-text" id="terms-error">
               Please check this box to agree before submitting.
             </p>
           </div>
         </div>
       `;

       const ConsentForm = () => `
         <form class="consent-form" novalidate>
           ${FormField()}
           <button class="submit-button" type="submit">Submit consent</button>
           <p class="status-message" id="form-status" aria-live="polite"></p>
         </form>
       `;

       const App = () => `
         <main class="page-shell" id="main-content">
           <section class="card" aria-labelledby="page-title">
             <div class="card-header">
               <p class="eyebrow">Secure signup</p>
               <h1 id="page-title">Review and accept the terms</h1>
               <p class="intro" id="terms-summary">
                 Confirm your consent to complete this quick setup step.
               </p>
             </div>
             ${ConsentForm()}
           </section>
         </main>
       `;

       const root = document.querySelector("#root");
       root.innerHTML = App();

       const form = document.querySelector(".consent-form");
       const checkbox = document.querySelector("#terms-consent");
       const error = document.querySelector("#terms-error");
       const status = document.querySelector("#form-status");

       const setValidationState = () => {
         const isValid = checkbox.checked;
         checkbox.setAttribute("aria-invalid", String(!isValid));
         error.classList.toggle("is-visible", !isValid);
         status.textContent = "";
         return isValid;
       };

       checkbox.addEventListener("change", setValidationState);

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!setValidationState()) {
           checkbox.focus();
           return;
         }

         status.textContent = "Thanks. Your consent has been recorded.";
       });
     </script>
   </body>
 </html>

